#!/usr/bin/env python3
"""Pack program images (raw binaries) into one C header for the Zynq host.

usage: bin2c.py <output.h> <name>=<file.bin> ...
"""
import sys


def main() -> None:
    if len(sys.argv) < 3:
        sys.exit(__doc__)
    out = ["// Program images for the AP SoC, generated by sw/tools/bin2c.py",
           "// from the programs in sw/ ('make -C sw zynq'). Do not edit.",
           "#ifndef AP_PROGRAMS_H", "#define AP_PROGRAMS_H", "",
           "#include <stdint.h>", ""]
    entries = []
    for arg in sys.argv[2:]:
        name, path = arg.split("=", 1)
        data = open(path, "rb").read()
        data += b"\0" * (-len(data) % 4)
        words = [int.from_bytes(data[i:i + 4], "little") for i in range(0, len(data), 4)]
        out.append(f"static const uint32_t prog_{name}[{len(words)}] = {{")
        for i in range(0, len(words), 6):
            out.append("    " + ", ".join(f"0x{w:08x}" for w in words[i:i + 6]) + ",")
        out.append("};")
        out.append("")
        entries.append((name, len(words)))
    out.append("struct ap_program {")
    out.append("    const char     *name;")
    out.append("    const uint32_t *words;")
    out.append("    uint32_t        nwords;")
    out.append("};")
    out.append("")
    out.append("static const struct ap_program ap_programs[] = {")
    for name, n in entries:
        out.append(f'    {{ "{name}", prog_{name}, {n} }},')
    out.append("};")
    out.append("")
    out.append(f"#define AP_NUM_PROGRAMS {len(entries)}")
    out.append("")
    out.append("#endif")
    with open(sys.argv[1], "w") as f:
        f.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
